import os

# 要验证的文件列表
files = [
    r"F:\qgis_project\autoc\fallback\exports\河南省行军路线图.pdf",
    r"F:\qgis_project\autoc\fallback\exports\河南省行军路线图.png"
]

results = []
for f in files:
    exists = os.path.isfile(f)
    size = os.path.getsize(f) if exists else 0
    results.append({
        "path": f,
        "exists": exists,
        "size_bytes": size
    })

# 如果文件不存在，在 F:\qgis_project\autoc 下查找类似的 pdf/png
search_base = r"F:\qgis_project\autoc"
similar_files = []

if os.path.isdir(search_base):
    for root, dirs, filenames in os.walk(search_base):
        for fn in filenames:
            if fn.lower().endswith(('.pdf', '.png')):
                full_path = os.path.join(root, fn)
                similar_files.append(full_path)

print("=== 文件验证结果 ===")
for r in results:
    status = "✅ 存在" if r["exists"] else "❌ 不存在"
    print(f"{status}: {r['path']}" + (f" ({r['size_bytes']} bytes)" if r['exists'] else ""))

if any(not r['exists'] for r in results):
    print(f"\n=== 在 {search_base} 目录下找到的类似文件 ({len(similar_files)} 个) ===")
    for sf in sorted(similar_files):
        size = os.path.getsize(sf)
        print(f"  📄 {sf} ({size} bytes)")
else:
    print("\n所有文件均已存在，无需查找。")

