    })

# 在 F:\qgis_project\autoc 下查找类似的 pdf/png
search_base = r"F:\qgis_project\autoc"
similar_files = []

dir_info = QDir(search_base)
if dir_info.exists():
    def collect_files(directory):
        d = QDir(directory)
        entries = d.entryInfoList(QDir.Files | QDir.Dirs | QDir.NoDotAndDotDot)
        result = []
        for entry in entries:
            if entry.isDir():
                result.extend(collect_files(entry.absoluteFilePath()))
            elif entry.isFile():
                name = entry.fileName().lower()
                if name.endswith('.pdf') or name.endswith('.png'):
                    result.append(entry.absoluteFilePath())
        return result
    similar_files = collect_files(search_base)

print("=== 文件验证结果 ===")
